package com.weearntogether.play

import android.animation.Animator
import android.animation.AnimatorListenerAdapter
import android.animation.ValueAnimator
import android.content.Context
import android.graphics.Color
import android.graphics.Typeface
import android.graphics.drawable.GradientDrawable
import android.view.Gravity
import android.view.HapticFeedbackConstants
import android.view.MotionEvent
import android.view.View
import android.view.animation.DecelerateInterpolator
import android.widget.FrameLayout
import android.widget.TextView
import kotlin.math.cos
import kotlin.math.max
import kotlin.math.sin
import kotlin.random.Random

class PremiumBubbleShooterView(context: Context, private val onLevelComplete: () -> Unit = {}) : FrameLayout(context) {
 private val prefs=ProgressPreferences.open(context,"bubble_shooter_hd2d"); private val rows=10; private val cols=9; private val grid=Array(rows){IntArray(cols)}
 private val palette=intArrayOf(0xff35c6fa.toInt(),0xffa478ff.toInt(),0xffffc857.toInt(),0xff49e1aa.toInt(),0xffff638f.toInt()); private val field=FrameLayout(context); private val hud=TextView(context); private val danger=TextView(context); private val launcher=TextView(context); private val nextView=TextView(context); private val aimDots=mutableListOf<View>(); private val fxLayer=FrameLayout(context)
 private var score=0;private var best=0;private var level=1;private var streak=0;private var current=1;private var next=2;private var misses=0;private var busy=false;private var cell=1;private var fieldTop=0;private var aimingCol=-1
 init{setBackgroundColor(0xff071020.toInt());field.background=GradientDrawable(GradientDrawable.Orientation.TL_BR,intArrayOf(0xff0a1734.toInt(),0xff211047.toInt(),0xff071a38.toInt())).apply{cornerRadius=dp(24).toFloat();setStroke(dp(1),0x6658c8ff)};addView(field,LayoutParams(-1,-1).apply{setMargins(dp(12),dp(116),dp(12),dp(92))});addView(fxLayer,LayoutParams(-1,-1));fxLayer.isClickable=false;hud.apply{setTextColor(Color.WHITE);textSize=14f;gravity=Gravity.CENTER;setTypeface(null,Typeface.BOLD)};addView(hud,LayoutParams(-1,dp(48),Gravity.TOP).apply{topMargin=dp(112)});danger.apply{textSize=11f;gravity=Gravity.CENTER;setTypeface(null,Typeface.BOLD)};addView(danger,LayoutParams(-1,dp(28),Gravity.TOP).apply{topMargin=dp(158)});launcher.gravity=Gravity.CENTER;launcher.text="●";launcher.textSize=40f;launcher.elevation=dp(12).toFloat();addView(launcher,LayoutParams(dp(66),dp(66),Gravity.BOTTOM or Gravity.CENTER_HORIZONTAL).apply{bottomMargin=dp(12)});nextView.gravity=Gravity.CENTER;nextView.textSize=22f;addView(nextView,LayoutParams(dp(48),dp(48),Gravity.BOTTOM or Gravity.CENTER_HORIZONTAL).apply{bottomMargin=dp(18);leftMargin=dp(116)});repeat(10){val d=View(context).apply{visibility=View.GONE;background=GradientDrawable().apply{shape=GradientDrawable.OVAL;setColor(0xddffffff.toInt());setStroke(dp(1),0x99ffc857.toInt())}};aimDots+=d;addView(d,LayoutParams(dp(8),dp(8)))};restoreOrNew();post{rebuild()}}
 private fun dp(v:Int)=(v*resources.displayMetrics.density).toInt();private fun light(c:Int)=Color.rgb((Color.red(c)+80).coerceAtMost(255),(Color.green(c)+80).coerceAtMost(255),(Color.blue(c)+80).coerceAtMost(255));private fun shade(c:Int)=Color.rgb((Color.red(c)*.58f).toInt(),(Color.green(c)*.58f).toInt(),(Color.blue(c)*.58f).toInt());private fun bubble(c:Int)=GradientDrawable(GradientDrawable.Orientation.TL_BR,intArrayOf(light(c),c,shade(c))).apply{shape=GradientDrawable.OVAL;setStroke(dp(2),0x99ffffff.toInt())}
 private fun restoreOrNew(){val raw=prefs.getString("grid",null)?.split(',')?.mapNotNull{it.toIntOrNull()};if(raw?.size==rows*cols)raw.forEachIndexed{i,v->grid[i/cols][i%cols]=v.coerceIn(0,palette.size)}else newBoard();score=prefs.getInt("score",0);best=prefs.getInt("best",0);level=prefs.getInt("level",1).coerceIn(1,250);streak=prefs.getInt("streak",0);misses=prefs.getInt("misses",0);current=prefs.getInt("current",randomBoardColor()).coerceIn(1,palette.size);next=prefs.getInt("next",randomBoardColor()).coerceIn(1,palette.size)}
 private fun newBoard(){grid.forEach{it.fill(0)};val fill=(4+level/35).coerceAtMost(7);for(r in 0 until fill)for(c in 0 until cols)if(Random.nextFloat()>.08f)grid[r][c]=1+Random.nextInt((3+level/45).coerceAtMost(palette.size));misses=0}
 private fun save(){best=max(best,score);prefs.edit().putString("grid",grid.flatMap{it.asList()}.joinToString(",")).putInt("score",score).putInt("best",best).putInt("level",level).putInt("streak",streak).putInt("misses",misses).putInt("current",current).putInt("next",next).apply()}
 private fun pressureLimit()=(6-level/55).coerceAtLeast(3)
 private fun rebuild(){field.removeAllViews();cell=((field.width-dp(16))/cols).coerceAtLeast(dp(30));fieldTop=dp(72);for(r in 0 until rows)for(c in 0 until cols)if(grid[r][c]>0)addBubble(r,c,grid[r][c]);launcher.setTextColor(palette[current-1]);launcher.background=bubble(palette[current-1]);nextView.setTextColor(palette[next-1]);nextView.text="●";nextView.background=bubble(palette[next-1]);hud.text="SCORE  $score     BEST  $best     LEVEL  $level/250\nSTREAK  x$streak     NEXT";danger.text="PRESSURE  $misses/${pressureLimit()}  •  "+if(misses>=pressureLimit()-1)"DANGER — CLEAR 3+!" else "POP 3+ TO LOWER PRESSURE";danger.setTextColor(if(misses>=pressureLimit()-1)0xffff638f.toInt() else 0xffffc857.toInt())}
 private fun addBubble(r:Int,c:Int,v:Int){field.addView(TextView(context).apply{gravity=Gravity.CENTER;text="•";setTextColor(0xaaffffff.toInt());background=bubble(palette[v-1]);elevation=dp(7).toFloat()},LayoutParams(cell-dp(5),cell-dp(5)).apply{leftMargin=dp(8)+c*cell;topMargin=fieldTop+r*cell})}
 override fun onTouchEvent(e:MotionEvent):Boolean{if(busy)return true;when(e.actionMasked){MotionEvent.ACTION_DOWN,MotionEvent.ACTION_MOVE->{if(e.y<field.top+fieldTop||e.y>height-dp(54)){hideAim();return true};updateAim(e.x)};MotionEvent.ACTION_UP->{val c=aimingCol;hideAim();if(c>=0)shoot(c)};MotionEvent.ACTION_CANCEL->hideAim()};return true}
 private fun updateAim(x:Float){val c=((x-field.left).coerceIn(0f,field.width.toFloat())/cell).toInt().coerceIn(0,cols-1);val r=landingRow(c);if(r<0){hideAim();return};aimingCol=c;val sx=width/2f;val sy=height-dp(45).toFloat();val ex=field.left+dp(8)+c*cell+(cell-dp(5))/2f;val ey=field.top+fieldTop+r*cell+(cell-dp(5))/2f;aimDots.forEachIndexed{i,d->val t=(i+1f)/(aimDots.size+1f);d.x=sx+(ex-sx)*t;d.y=sy+(ey-sy)*t;d.visibility=View.VISIBLE}}
 private fun hideAim(){aimingCol=-1;aimDots.forEach{it.visibility=View.GONE}}
 private fun landingRow(c:Int):Int{for(r in rows-1 downTo 0)if(grid[r][c]!=0)return if(r+1<rows)r+1 else -1;return 0}
 private fun shoot(c:Int){val r=landingRow(c);if(r<0)return;busy=true;val p=View(context).apply{background=bubble(palette[current-1]);elevation=dp(18).toFloat()};val size=cell-dp(4);addView(p,LayoutParams(size,size).apply{leftMargin=width/2-size/2;topMargin=height-dp(84)});val sx=width/2f-size/2;val sy=height-dp(84).toFloat();val tx=field.left+dp(8)+c*cell.toFloat();val ty=field.top+fieldTop+r*cell.toFloat();ValueAnimator.ofFloat(0f,1f).apply{duration=(260L-level/3L).coerceAtLeast(150L);interpolator=DecelerateInterpolator();addUpdateListener{a->val t=a.animatedValue as Float;p.x=sx+(tx-sx)*t;p.y=sy+(ty-sy)*t};addListener(object:AnimatorListenerAdapter(){override fun onAnimationEnd(a:Animator){removeView(p);settle(r,c)}});start()}}
 private fun settle(r:Int,c:Int){grid[r][c]=current;val g=flood(r,c,current);if(g.size>=3){val color=current;g.forEach{(rr,cc)->grid[rr][cc]=0};val dropped=disconnectedCells().map{(rr,cc)->Triple(rr,cc,grid[rr][cc])};dropped.forEach{(rr,cc,_)->grid[rr][cc]=0};streak++;misses=(misses-2).coerceAtLeast(0);score+=g.size*45*level+dropped.size*70*level+streak*30;popFx(g,color,dropped);performHapticFeedback(HapticFeedbackConstants.LONG_PRESS)}else{streak=0;misses++;score+=10*level};if(misses>=pressureLimit()){pushPressureRow();misses=0;performHapticFeedback(HapticFeedbackConstants.REJECT)};if(grid.all{row->row.all{it==0}}){level=(level+1).coerceAtMost(250);post { onLevelComplete() };score+=level*500;newBoard()};if(grid[rows-1].any{it!=0}){score=(score-level*150).coerceAtLeast(0);newBoard()};current=next;next=randomBoardColor();save();if(g.size>=3)postDelayed({busy=false;rebuild()},430)else{busy=false;rebuild()}}
 private fun popFx(group:Set<Pair<Int,Int>>,color:Int,dropped:List<Triple<Int,Int,Int>>){val baseColor=palette[color-1];group.forEachIndexed{i,(r,c)->val x=field.left+dp(8)+c*cell+cell/2;val y=field.top+fieldTop+r*cell+cell/2;repeat(5){k->val spark=View(context).apply{background=GradientDrawable().apply{shape=GradientDrawable.OVAL;setColor(if(k%2==0)0xffffd56a.toInt() else baseColor)};elevation=dp(20).toFloat()};val s=dp(7);fxLayer.addView(spark,LayoutParams(s,s).apply{leftMargin=x-s/2;topMargin=y-s/2});val angle=(k*72+i*19)*Math.PI/180.0;val dist=dp(24+(k%3)*8).toFloat();spark.animate().translationX((cos(angle)*dist).toFloat()).translationY((sin(angle)*dist).toFloat()).scaleX(.15f).scaleY(.15f).alpha(0f).setDuration(300).withEndAction{fxLayer.removeView(spark)}.start()}};dropped.forEachIndexed{i,(r,c,v)->val ghost=View(context).apply{background=bubble(palette[(v-1).coerceIn(0,palette.lastIndex)]);alpha=.9f;elevation=dp(12).toFloat()};val s=cell-dp(5);fxLayer.addView(ghost,LayoutParams(s,s).apply{leftMargin=field.left+dp(8)+c*cell;topMargin=field.top+fieldTop+r*cell});ghost.animate().translationY(dp(145+(i%4)*28).toFloat()).rotationBy(if(i%2==0)42f else -42f).scaleX(.7f).scaleY(.7f).alpha(0f).setDuration(430).withEndAction{fxLayer.removeView(ghost)}.start()};field.animate().scaleX(1.012f).scaleY(1.012f).setDuration(80).withEndAction{field.animate().scaleX(1f).scaleY(1f).setDuration(130).start()}.start()}
 private fun pushPressureRow(){for(r in rows-1 downTo 1)for(c in 0 until cols)grid[r][c]=grid[r-1][c];val colors=(3+level/45).coerceAtMost(palette.size);for(c in 0 until cols)grid[0][c]=if(Random.nextFloat()>.12f)1+Random.nextInt(colors) else 0}
 private fun flood(sr:Int,sc:Int,color:Int):Set<Pair<Int,Int>>{val seen=linkedSetOf<Pair<Int,Int>>();val q=ArrayDeque<Pair<Int,Int>>();q.add(sr to sc);while(q.isNotEmpty()){val p=q.removeFirst();if(p in seen)continue;val(r,c)=p;if(r !in 0 until rows||c !in 0 until cols||grid[r][c]!=color)continue;seen.add(p);q.add(r-1 to c);q.add(r+1 to c);q.add(r to c-1);q.add(r to c+1)};return seen}
 private fun disconnectedCells():Set<Pair<Int,Int>>{val keep=mutableSetOf<Pair<Int,Int>>();val q=ArrayDeque<Pair<Int,Int>>();for(c in 0 until cols)if(grid[0][c]!=0)q.add(0 to c);while(q.isNotEmpty()){val p=q.removeFirst();if(!keep.add(p))continue;val(r,c)=p;arrayOf(r-1 to c,r+1 to c,r to c-1,r to c+1).forEach{(rr,cc)->if(rr in 0 until rows&&cc in 0 until cols&&grid[rr][cc]!=0&&(rr to cc)!in keep)q.add(rr to cc)}};val out=linkedSetOf<Pair<Int,Int>>();for(r in 0 until rows)for(c in 0 until cols)if(grid[r][c]!=0&&(r to c)!in keep)out+=r to c;return out}
 private fun randomBoardColor():Int{val a=mutableListOf<Int>();for(r in 0 until rows)for(c in 0 until cols)if(grid[r][c]>0&&grid[r][c] !in a)a+=grid[r][c];return if(a.isEmpty())1+Random.nextInt(palette.size)else a.random()}
 fun swapBubble(){if(busy)return;val t=current;current=next;next=t;save();rebuild()};fun restart(){if(busy)return;score=0;streak=0;misses=0;newBoard();current=randomBoardColor();next=randomBoardColor();save();rebuild()}
    fun videoRescue(){if(busy)return;for(r in (rows-3) until rows)grid[r].fill(0);misses=0;save();rebuild()}

}
